insert into public.outreach_contacts
  (company, segment, country, city, email, phone, website, notes, status, language)
values
  ('1. Österreichischer Wellenreitverein', 'Surf school', 'Austria', '(Austria)', 'info@viele.at', null, 'https://www.verein-viele.at/1-oesterreichischer-wellenreitverein/', 'IG:  | 1st Austrian Wave-Riding Association; offers members discounted surf-camp participation - explicitly partners with surf camps. Direct B2B angle.', 'not_started', 'en'),
  ('MOON / Moon Studio (Movements of Ocean and Nature)', 'Yoga / wellness retreat', 'Austria', 'Vienna', 'office@moonstudiovienna.at', null, 'https://www.moonmovements.at', 'IG: @moon.movements | Vienna yoga/surfskate studio focused on board sports. Landlocked Austrian community that travels to surf - ideal retreat-group source.', 'not_started', 'en'),
  ('Riversurfing Austria (IG Flusssurfen Österreich)', 'Surf school', 'Austria', 'Salzburg', 'vorstand@riversurfing-austria.at', null, 'https://riversurfing-austria.at', 'IG: @riversurfingaustria | Austria''s river-surf community/Verein (Almwelle Salzburg). Members are landlocked surfers who travel for ocean waves - prime camp audience. Contact via Impressum/Presse.', 'not_started', 'en'),
  ('SurfnYoga House Vienna', 'Yoga / wellness retreat', 'Austria', 'Vienna', 'hello@surfnyogahouse.com', null, 'http://www.surfnyogahouse.com', 'IG: @surfnyogahouse | Vienna-based surf prep + yoga; trains surfers before surf trips. Pre/post trip workouts = pipeline of trip-ready surfers.', 'not_started', 'en'),
  ('International Surf Club Brussels', 'Surf club', 'Belgium', 'Brussels', null, null, 'https://www.meetup.com/international-surf-club-in-brussels/', 'IG:  | Multinational Brussels surf community (Meetup). Members live far from waves and organise trips - strong group-booking partner. Contact via Meetup organisers.', 'not_started', 'en'),
  ('Surfive', 'Yoga / wellness retreat', 'Belgium', '(Belgium)', null, null, 'https://www.facebook.com/surfive.be', 'IG: @surfive.be | Belgian organiser running surf retreats with psychological guidance + yoga + surf for mental wellbeing. Landlocked-coast audience travels to surf.', 'not_started', 'en'),
  ('Surf-Trip.cz (Czech Surf s.r.o.)', 'Yoga / wellness retreat', 'Czechia', 'Prague', 'crew@surf-trip.cz', null, 'https://www.surf-trip.cz/', 'IG: @surf_trip.cz | Largest Czech surf travel agency (since 2007); surf camps + yoga stays in Portugal, Sri Lanka, France, Spain, Lanzarote, Bali. Own Sea You House on Sri Lanka. ISA instructors. Serves CZ & SK.', 'not_started', 'en'),
  ('Surfcamp.cz', 'Travel agency / DMC', 'Czechia', 'Czechia', 'info@surftravel.cz', null, 'https://www.surfcamp.cz/', 'IG: @surfcampcz | Czech organiser running trips to Portugal (Peniche), Morocco, Bali, Panama. Licensed CZ + local instructors, video coaching. Overlaps Gota d''Agua destinations.', 'not_started', 'en'),
  ('Cold Hawaii Surf Camp', 'Surf school', 'Denmark', 'Klitmøller', null, null, 'https://coldhawaiisurfcamp.com', 'IG: @coldhawaiisurf | Run by multi-time Danish champions; surf school+camp+café since 2010 in Denmark''s surf HQ. Many students seek warm-water trips.', 'not_started', 'en'),
  ('DBP Adventures (De Brede Planker)', 'Surf school', 'Denmark', 'Copenhagen', 'rejsmed@debredeplanker.dk', null, 'https://dbpadventures.com', 'IG: @debredeplanker | Leading Danish surf-trip organiser already running trips to Morocco, Portugal, Sri Lanka, Bali. Direct B2B fit - they sell exactly Gota d''Agua''s destinations.', 'not_started', 'en'),
  ('Viking Surf House', 'Surf school', 'Denmark', 'Klitmøller', 'kontakt@vikingsurfhouse.dk', null, 'https://www.vikingsurfhouse.dk/en', 'IG: @vikingsurfhouse | Surf school/camp in Klitmøller (Cold Hawaii) run by Peter Strøbech & Erik Jensen. Established Danish surf audience for southern partner camps.', 'not_started', 'en'),
  ('drivethru Surfcamp', 'Surf school', 'Denmark', 'Hvide Sande', 'booking@drivethru.de', null, 'https://www.surfholidays.com', 'IG: @drivethrusurfcamp | Surf+yoga camp operating in Denmark & Sri Lanka; runs yoga retreat packages. Nordic surf audience that travels south.', 'not_started', 'en'),
  ('The Salty (Surf & Yoga)', 'Yoga / wellness retreat', 'Denmark/Intl', 'Ericeira, Portugal (base)', null, null, 'https://www.thesalty.co', 'IG: @thesaltyco | Surf, yoga & social-wellness retreat brand with bases incl. Portugal (Ericeira) & Sri Lanka; markets to Nordic wellness travellers.', 'not_started', 'en'),
  ('Suomen Lainelautaliitto (Finnish Surfing Association)', 'Surf club', 'Finland', 'Helsinki', 'info@lainelautaliitto.fi', null, 'https://www.lainelautaliitto.fi', 'IG: @lainelautaliitto | Finland''s national surfing association (chair Tanja Piha, female-majority board). Gateway to Finnish surf community that must travel abroad to surf.', 'not_started', 'en'),
  ('Suomen SUP-liitto ry (Finnish SUP & Surf Federation)', 'Surf club', 'Finland', 'Söderkulla', 'suomensupliitto@gmail.com', null, 'https://www.finssf.fi', 'IG:  | Finland''s official ISA member federation. Finnish surfers nearly all travel south - strong audience referral partner.', 'not_started', 'en'),
  ('Surfing ry', 'Surf school', 'Finland', 'Espoo', null, null, 'https://surfing.fi', 'IG:  | Local Finnish surf club (Espoo, active since the 1970s). Community of Baltic surfers who travel for real waves.', 'not_started', 'en'),
  ('Bonbon Community', 'Yoga / wellness retreat', 'France', 'Biarritz', null, null, 'https://www.bonboncommunity.com/', 'IG: @bonboncommunity | Women-led wellness/surf/yoga retreats (Casaviel, Biarritz/Bidart), ''hedonistic twist''. Also runs corporate/private events. Open to all genders. Contact via site form; IG active.', 'not_started', 'en'),
  ('Cam''s Yoga', 'Yoga / wellness retreat', 'France', 'Bretagne', 'studio@camsyoga.fr', null, 'https://www.camsyoga.fr/project/stage-yoga-surf-2022/', 'IG: @cams_yoga | Yoga teacher (Camille) running yoga+surf retreats. Small wellness host; potential surf-trip partner.', 'not_started', 'en'),
  ('Chill Surf School', 'Surf school', 'France', 'Seignosse', 'chill.surfschool@gmail.com', null, 'https://chillsurfschool.fr/en/', 'IG: @chillsurfschool | Surf school & surf camps in Seignosse (group & private lessons). Small operator that organises surf stays; warm-water winter trips a logical add-on.', 'not_started', 'en'),
  ('Coaching & Yoga Hossegor (Marie Corrihons)', 'Yoga / wellness retreat', 'France', 'Hossegor / Capbreton', 'contact@coaching-yoga-hossegor.fr', null, 'https://www.coaching-yoga-hossegor.fr/retraite-de-yoga', 'IG: @yoga_hossegor | Sports physiotherapist & yoga teacher since 2018; runs Surf x Yoga retreats in Capbreton. Credible wellness pro for surf+yoga partnerships.', 'not_started', 'en'),
  ('Marie Olivia Yoga', 'Yoga / wellness retreat', 'France', 'Hossegor', 'hello@marieoliviayoga.com', null, 'https://marieoliviayoga.com/retraite-yoga-france-2026/', 'IG: @marieoliviayoga | Runs yoga retreats at Southwest Surf House near Estagnots beach, Hossegor. Wellness teacher hosting surf-adjacent retreats.', 'not_started', 'en'),
  ('Mood Goyave', 'Yoga / wellness retreat', 'France', 'Soustons / Landes', 'hello@moodgoyave.com', null, 'https://www.moodgoyave.com/tour/retraite-surf-yoga/', 'IG: @moodgoyave | Surf & yoga ''Eaudyssee'' retreat in the Landes (15 min from Hossegor). Creative/poetic yoga + body movement; retreat organiser open to new destinations.', 'not_started', 'en'),
  ('My Yoga Wave (Hossegor)', 'Yoga / wellness retreat', 'France', 'Hossegor', 'myyogawave@gmail.com', null, 'https://www.myyogawave.com/', 'IG: @myyogawave | Hossegor yoga teacher offering classes, workshops and retreats. Wellness teacher who could host surf+yoga retreats abroad.', 'not_started', 'en'),
  ('Namastrip', 'Yoga / wellness retreat', 'France', 'Bretagne / multi', 'hello@namastrip.com', null, 'https://namastrip.com/', 'IG: @namastrip | Travel agency curating yoga & wellness stays incl. surf+yoga retreats in Brittany. B2B-minded operator that could resell Gota d''Agua camps.', 'not_started', 'en'),
  ('Ocean Adventure (Hossegor Nature)', 'Surf school', 'France', 'Seignosse / Biarritz', 'partners@oceanadventure.surf', null, 'https://oceanadventure.surf/en/', 'IG: @oceanadventure.surf | Surf camps for groups (adults & teens) in Seignosse and Biarritz. Group-trip organiser; candidate to partner on overseas surf travel.', 'not_started', 'en'),
  ('Oumono Club', 'Yoga / wellness retreat', 'France', 'Hossegor', 'hello@oumonoclub.com', null, 'https://oumonoclub.com/hossegor', 'IG: @oumonoclub | All-female surf, yoga & skate retreats based in Hossegor. Community-driven women''s collective; ideal partner for women''s surf travel.', 'not_started', 'en'),
  ('Shaka Yoga Hossegor', 'Yoga / wellness retreat', 'France', 'Hossegor', 'adele.shakayoga@gmail.com', null, 'https://www.shakayogahossegor.com/retraite-yoga-surf', 'IG: @shakayogahossegor | Yoga studio in Hossegor hosting yoga+surf retreats. Local wellness teacher, good fit for surf+yoga retreat partnerships. Contact via site.', 'not_started', 'en'),
  ('Studio Soleil Yoga (Louise)', 'Yoga / wellness retreat', 'France', 'La Torche / Bretagne', null, null, 'https://www.studio-soleil-yoga.com/retraite-yoga-surf-a-la-torche', 'IG: @studiosoleilyoga | Yoga teacher Louise running yoga+surf retreats at La Torche, Brittany. Independent wellness host open to new retreat locations.', 'not_started', 'en'),
  ('The Commodore Hostel (Ian Fontaine surf coaching)', 'Surf school', 'France', 'Bretagne', null, null, 'https://thecommodorehostel.com/en/surf-trips-2/pro-surf-trip/', 'IG: @thecommodorehostel | Surf trips & video-coaching with pro surfer Ian Fontaine in Brittany. Coach/trip organiser; could route advanced groups to Portugal/Morocco.', 'not_started', 'en'),
  ('UnaMyoga', 'Yoga / wellness retreat', 'France', 'La Torche / Finistere', 'contact@unamyoga.com', null, 'https://www.unamyoga.com/retraite-surf-yoga-en-bretagne', 'IG: @unamyoga | Organises yoga & surf weekends/weeks in Brittany (La Torche). Yoga retreat host; potential to add Portugal/Morocco trips.', 'not_started', 'en'),
  ('Vanayoga (Audierne)', 'Yoga / wellness retreat', 'France', 'Audierne / Bretagne', 'juliette@vanayoga.fr', null, 'https://www.vanayoga.fr/retraite-yoga-surf-bretagne/', 'IG: @vanayoga | Yoga, surf & plant-based cuisine retreats in Brittany. Independent yoga teacher/host, candidate for surf-travel collaboration.', 'not_started', 'en'),
  ('Yoga Searcher Hossegor', 'Yoga / wellness retreat', 'France', 'Hossegor', 'contact@yogasearcher-hossegor.com', null, 'https://yogasearcher.com/en/pages/retraite-surf-yoga', 'IG: @yogasearcherhossegor | Surf & yoga retreats 10 min from Hossegor beaches (host Nathalie). Founder ex-Rip Curl marketing, also created a Surf&Yoga concept in Morocco - clear travel-to-surf affinity. 13K IG.', 'not_started', 'en'),
  ('A-Frame Surfcamp', 'Yoga / wellness retreat', 'Germany', '(operates Andalusia, Spain)', 'info@aframe.de', null, 'https://aframe.de', 'IG: @aframe.surfcamp | Runs women''s surf+yoga and Pilates+yoga+surf retreats (''Surf the Moment''). Established retreat brand for German market.', 'not_started', 'en'),
  ('Drop In Sport e.V.', 'Surf school', 'Germany', 'Berlin', 'info@dropin-ev.de', null, 'https://dropin-ev.de', 'IG: @dropin.ev | Berlin surf club (DWV member). City/landlocked community - members travel to ocean. Verein with trip-organising potential.', 'not_started', 'en'),
  ('GET WET SOON (Thomas Zielinski)', 'Yoga / wellness retreat', 'Germany', 'Hamburg', 'mail@getwetsoon.de', null, 'https://getwetsoon.de', 'IG: @getwetsoon | Jivamukti yoga teacher + ISA surf coach, runs surf+yoga retreats in Portugal & Sri Lanka. Podcaster. Exact same destinations as Gota d''Agua. Contact via site form/IG.', 'not_started', 'en'),
  ('IGSM - Interessengemeinschaft Surfen in München', 'Surf school', 'Germany', 'Munich', 'info@eisbachwelle.de', null, 'https://www.eisbachwelle.de', 'IG: @eisbachwelle | Represents ~2000 Munich river surfers (Eisbach). Huge city surf community - landlocked surfers who travel for ocean waves. Top-tier audience partner.', 'not_started', 'en'),
  ('Lahnwelle e.V.', 'Surf school', 'Germany', 'Gießen', 'info@lahnwelle.com', null, 'http://www.lahnwelle.com', 'IG: @lahnwelle | River-surf Verein on the Lahn river (DWV member). Inland surfers who travel for ocean waves.', 'not_started', 'en'),
  ('Leinewelle e.V.', 'Surf school', 'Germany', 'Hannover', 'info@leinewelle.de', null, 'https://www.enercity-leinewelle.de', 'IG: @leinewelle | River wave Verein in Hannover (DWV member). Active inland surf community.', 'not_started', 'en'),
  ('No Shore Surfclub Cologne e.V.', 'Surf club', 'Germany', 'Cologne', 'info@noshore.de', null, 'https://wellenreitverband.de', 'IG: @noshore_surfclub | Cologne surf club (DWV member, founded 2008). Inland surfers travelling for waves - ideal camp partner.', 'not_started', 'en'),
  ('Nürnberger Dauerwelle e.V.', 'Surf school', 'Germany', 'Nuremberg', 'info@nuernberger-dauerwelle.de', null, 'https://www.nuernberger-dauerwelle.de', 'IG: @nuernberger_dauerwelle | Nuremberg river-wave Verein. Landlocked Bavarian surf community.', 'not_started', 'en'),
  ('Open Ocean e.V.', 'Surf school', 'Germany', 'Cologne', 'hallo@open-ocean.info', null, 'https://open-ocean.info', 'IG: @openocean.ev | Cologne surf club (DWV member, founded 2022). Younger inland community, trip-oriented.', 'not_started', 'en'),
  ('Surf Spirit', 'Yoga / wellness retreat', 'Germany', 'Bielefeld', 'hello@surf-spirit.com', null, 'https://surf-spirit.com', 'IG: @surf_spirit | Runs surf+yoga retreats in Sri Lanka, Spain, Portugal with certified coaches. Has ''Host Your Retreat'' program - clear B2B fit. WhatsApp +4915679505600.', 'not_started', 'en'),
  ('Surfclub Leonberg e.V.', 'Surf club', 'Germany', 'Leonberg', 'info@surfclub-leonberg.de', null, 'http://www.surfclub-leonberg.de', 'IG:  | Baden-Württemberg surf club (DWV member). Inland members travel to ocean spots for camps.', 'not_started', 'en'),
  ('Surfpirates Flensburg', 'University / student', 'Germany', 'Flensburg', 'info@surfpirates.de', null, 'https://wellenreitverband.de', 'IG: @surfpirates_flensburg | Student surf group in Flensburg. Student community that organises surf trips abroad.', 'not_started', 'en'),
  ('layday e.V. (Layday Surfclub)', 'Surf club', 'Germany', 'Düsseldorf', null, null, 'https://layday-surfclub.de', 'IG: @layday_surfclub | Düsseldorf city surf club (DWV member). Landlocked-city surfers, group surf-trip audience.', 'not_started', 'en'),
  ('meermoment surf & yoga', 'Yoga / wellness retreat', 'Germany', 'Sylt', 'info@meermoment.de', null, 'https://www.meermoment.de', 'IG: @meermoment_surfandyoga | 15+ yrs running beach yoga + surf weeks on Sylt; audience of cold-water Germans who travel to surf warm waters in winter.', 'not_started', 'en'),
  ('sea you soon / Dancers of the Oceans (Sabine Rabes)', 'Yoga / wellness retreat', 'Germany', '(online community)', 'sabine@seayousoon.de', null, 'https://www.seayousoon.de', 'IG: @seayousoon.de | Best-known German women''s surf blog + large FB community ''Dancers of the Oceans''. Strong audience reach for partnerships/affiliate. Contact via /kontakt/ page.', 'not_started', 'en'),
  ('surft. kologne (Romi & Viki)', 'Yoga / wellness retreat', 'Germany', 'Cologne', 'hallo@surftkologne.de', null, 'https://surftkologne.de', 'IG: @surftkologne | Women-for-women surf+yoga+empowerment retreats. City surf community with physical ''surft. haus''. Phone/WhatsApp 0174 194 00 71.', 'not_started', 'en'),
  ('Magyar Hullamlovaglas (Hungarian Wave Riding)', 'Travel agency / DMC', 'Hungary', 'Budapest', null, null, 'https://hullamlovaglas.hu/', 'IG: @hullamlovaglas | Hungarian organiser of surf camps & trips to exotic/ocean surf spots, family-oriented, led by experienced watersports pros. Main Hungarian-language surf-trip gateway.', 'not_started', 'en'),
  ('Bundoran Surf Co', 'Yoga / wellness retreat', 'Ireland', 'Bundoran, Co. Donegal', 'info@bundoransurfco.com', null, 'https://bundoransurfco.com/surf-and-yoga/', 'IG: @bundoransurfco | Monthly surf + yoga weekends from March, surf lodge in Bundoran. Ireland''s surf capital - active group host.', 'not_started', 'en'),
  ('Burren Yoga Retreat', 'Yoga / wellness retreat', 'Ireland', 'Kinvara, Co. Galway (Burren)', 'dave@burrenyoga.com', null, 'https://burrenyoga.com/', 'IG: @burrenyoga | West-coast Ireland yoga retreat centre; partners with activity providers. Could add surf-travel collaborations.', 'not_started', 'en'),
  ('TurfnSurf Lodge & Surf School', 'Surf school', 'Ireland', 'Bundoran, Co. Donegal', 'info@turfnsurftours.com', null, 'https://www.turfnsurf.ie/', 'IG: @turfnsurf | Established Bundoran surf school & lodge running surf and yoga weekends. Group accommodation + coaching.', 'not_started', 'en'),
  ('Buggerru Surf & Yoga Camp', 'Yoga / wellness retreat', 'Italy', 'Buggerru (Sardegna)', 'buggerrusurfschool@hotmail.com', null, 'https://www.buggerrusurfschool.com/en/', 'IG: @buggerrusurfschool | Sardinian surf school combining surf, SUP, trekking + yoga camps. Could co-host or refer groups to overseas camps. Contact via site.', 'not_started', 'en'),
  ('Irene Guardala Yoga & Pilates Retreats', 'Yoga / wellness retreat', 'Italy', 'Italy', 'retreat@ireneguardala.it', null, 'https://www.ireneguardala.it/retreat', 'IG: @ireneguardala | Italian yoga/pilates teacher running her own retreats; potential to add a surf+yoga retreat partnering with a camp. Contact via site.', 'not_started', 'en'),
  ('Is Benas Surf Club', 'Surf club', 'Italy', 'San Vero Milis (Sardegna)', 'surf@isbenas.com', null, 'https://www.isbenas.com/scuolasurf.html', 'IG: @isbenassurfclub | First Italian surf school/club (since 1997), first surf camp in the Mediterranean. Weekly ISA courses; also runs Ayurveda yoga+surf retreats. Established network of surfers.', 'not_started', 'en'),
  ('Onde Nostre', 'Yoga / wellness retreat', 'Italy', 'Italy', 'contact@ssff.it', null, 'https://vimeo.com/channels/ondenostre', 'IG: @ondenostre | Italian surf collective of surfers/filmmakers/photographers preserving Italian surf culture. Community-driven, good cultural partner. Contact via IG/Vimeo.', 'not_started', 'en'),
  ('Soul Rider Camp', 'Travel agency / DMC', 'Italy', 'Italy', 'info@soulridercamp.com', null, 'https://soulridercamp.com/', 'IG:  | Italian surf camp / trip brand offering organised surf weeks abroad. Confirm contact + IG on site.', 'not_started', 'en'),
  ('SurfWeek (Wave Srl)', 'Travel agency / DMC', 'Italy', 'Padova', 'info@surfweek.it', null, 'https://www.surfweek.it/', 'IG: @surf_week | Italian tour operator running group surf trips to Portugal, Morocco, Sri Lanka, Spain etc. Strong community model; partner page exists. Contact via site support form.', 'not_started', 'en'),
  ('Tuttologic Surf', 'Surf school', 'Italy', 'Italy', 'info@tuttologicsurf.it', null, 'https://www.tuttologicsurf.it/', 'IG: @tuttologicsurf | Italian surf media/community (podcast, articles) by surfers for surfers; features yoga+surf instructors (Camilla Michetti, Meg Vibes). Useful partner/influencer hub.', 'not_started', 'en'),
  ('D.E.R.M. Studentenboardsportvereniging', 'University / student', 'Netherlands', '(NL student association)', 'info@derm.nl', null, 'https://www.derm.nl', 'IG: @derm_boardsports | Dutch student boardsport association (surf/snowboard/skate). Student groups organise trips - good fit for group surf-camp bookings.', 'not_started', 'en'),
  ('Jessica Scheper Yoga', 'Yoga / wellness retreat', 'Netherlands', 'Den Haag (Scheveningen)', 'hello@jessicascheper.com', null, 'https://jessicascheper.com', 'IG: @jessicascheper.yoga | Dutch yoga teacher running mini surf+yoga retreats for women in Scheveningen + abroad 2026. Independent host - direct B2B fit.', 'not_started', 'en'),
  ('Jumpteam Scheveningen', 'Surf school', 'Netherlands', 'Scheveningen (Den Haag)', 'leden@jumpteam.nl', null, 'https://www.jumpteam.nl', 'IG: @jumpteam_scheveningen | Volunteer-run wave-riding (brandingsport) association in Scheveningen. Active club whose members travel for better waves.', 'not_started', 'en'),
  ('Soul Surf ''n Yoga', 'Yoga / wellness retreat', 'Netherlands', '(NL based)', null, null, 'https://www.soulsurfnyoga.com', 'IG: @soulsurfnyoga | Empowerment-through-surf-&-yoga retreats for women. Organiser model that books destination camps.', 'not_started', 'en'),
  ('Surfana Collective', 'Yoga / wellness retreat', 'Netherlands', 'Bloemendaal aan Zee', 'info@surfana.com', null, 'https://www.surfana.com', 'IG: @surfana_collective | NL surf specialist with own surfclub, festival & yoga weekends (~20k IG). Big Dutch surf community that travels abroad off-season.', 'not_started', 'en'),
  ('Tasha''s Surfcamp', 'Yoga / wellness retreat', 'Netherlands', 'Scheveningen', 'natasha@tashasurfcamp.com', null, 'https://tashasurfcamp.com', 'IG: @tashasurfcamp | Runs surf+yoga retreats in Scheveningen, Texel + Portugal, Morocco, France. Established NL operator with overlapping destinations.', 'not_started', 'en'),
  ('NTNUI (NTNU student sports - Trondheim)', 'University / student', 'Norway', 'Trondheim', 'hovedstyret@ntnui.no', null, 'https://www.ntnu.edu/lifeandhousing/trondheim/student-life', 'IG: @ntnui | Norway''s largest university sports org (60+ activities) with outdoor/board-sport students. Student surf-trip audience; approach via student board-sport groups.', 'not_started', 'en'),
  ('Queens of the North', 'Yoga / wellness retreat', 'Norway', 'West coast / Lofoten', null, null, null, 'IG: @queens0fthenorth | IG community founded by Runa Andersen documenting Norway''s female cold-water surfers (20-30 active in Lofoten). Strong women''s-camp partner; contact via IG.', 'not_started', 'en'),
  ('Salty Souls / surf-n-turf Lofoten women''s group', 'Yoga / wellness retreat', 'Norway', 'Kabelvåg / Henningsvær, Lofoten', 'info@saltysoulsexperience.com', null, 'https://saltysoulsexperience.com/surfing-in-lofoten/', 'IG:  | ~27-strong women''s surf collective in Lofoten (mothers, singles who moved there). Tight community that travels for warm surf; reach via local surf network.', 'not_started', 'en'),
  ('Stad Surfing', 'Surf school', 'Norway', 'Hoddevik', 'info@stadsurfing.com', null, 'https://www.stadsurfing.no', 'IG: @stadsurfing | Surf lessons & accommodation in Hoddevik. Norwegian surfers who chase warm-water winters; potential trip-organizer partner.', 'not_started', 'en'),
  ('Surfschool.no', 'Surf school', 'Norway', 'Norway (west coast)', 'surfschool.no@gmail.com', null, 'https://surfschool.no/en/', 'IG:  | Norwegian surf school; teaches beginners who become target market for warm-water surf camps in Portugal/Morocco.', 'not_started', 'en'),
  ('AZS Surfing Student Camp (Akademicki Zwiazek Sportowy)', 'University / student', 'Poland', 'Warsaw', 'jedrzej.sieczych@wum.edu.pl', null, 'https://azs.wum.edu.pl/surfing-student-camp', 'IG: @azs | University sports association (AZS) running a surfing student camp (Taghazout/Morocco destination noted). Direct access to Polish university surf students. Largest student org in Poland.', 'not_started', 'en'),
  ('BSSURF', 'Yoga / wellness retreat', 'Poland', 'Poland', 'agnieszka@bssurf.pl', null, 'https://bssurf.pl/', 'IG: @bssurf | Polish organiser running camps in Morocco & Portugal; also runs women''s line ''Girls Surf Wild'' (women-only surf trips). Inclusive teaching program.', 'not_started', 'en'),
  ('Femi Camp', 'Yoga / wellness retreat', 'Poland', 'Jastarnia', 'kontakt@femicamp.pl', null, 'https://femicamp.pl/', 'IG: @femicamp | Holistic women-only surf & yoga camps (also Sardinia trips); 80% participants come solo. Collaboration of Akademia Surfingu & JOY in me. Wellness-focused female audience.', 'not_started', 'en'),
  ('GDINA Surf', 'Travel agency / DMC', 'Poland', 'Gdynia', 'gdinasurfcrew@gmail.com', null, 'https://gdina.surf/', 'IG: @gdina.surf | Self-described longest-operating organiser of Polish surf camps abroad; destinations Portugal, Spain, Morocco, Sri Lanka. Direct overlap with Gota d''Agua locations.', 'not_started', 'en'),
